{"type": "payment.failed", "id": "evt_02", "created": 1718000060, "data": {"payment_id": "pay_10", "reason": "card_declined"}}
{"type": "refund.created", "id": "evt_03", "created": 1718000120, "data": {"refund_id": "re_4", "payment_id": "pay_9", "amount_cents": 1000}}
{"type": "customer.updated", "id": "evt_04", "created": 1718000180, "data": {"customer_id": "cus_2", "email": "x@example.test"}}
