type Crawler struct {
	client *http.Client
	seen   map[string]bool
	broken []string
	wg     sync.WaitGroup
}

func NewCrawler() *Crawler {
	return &Crawler{
		client: &http.Client{Timeout: 10 * time.Second},
		seen:   make(map[string]bool),
	}
}

func (c *Crawler) Run(start string, depth int) []string {
	c.wg.Add(1)
	go c.visit(start, depth)
	c.wg.Wait()
	return c.broken
}

func (c *Crawler) visit(url string, depth int) {
	defer c.wg.Done()
	if depth == 0 || c.seen[url] {
		return
	}
	c.seen[url] = true

	resp, err := c.client.Get(url)
	if err != nil || resp.StatusCode >= 400 {
		c.broken = append(c.broken, url)
		return
	}
