```

Go maps are not safe for concurrent use. Every `visit` runs in its own goroutine and writes `c.seen` without a lock. When two writes overlap, the runtime detects it and kills the process. It's a `fatal error`, not a panic, so `recover` can't catch it. It's random because it depends on timing.

The same race exists in three more places:

- **`c.seen[url]` read + write:** two goroutines can both see "not seen" and both crawl the same URL.
- **`c.broken = append(...)`** from many goroutines: entries can get lost silently, without any crash.
- **`resp.Body` is never closed when the status is ≥ 400**, so those connections leak.

You also start an unbounded number of goroutines. A page with 500 links means 500 simultaneous requests to one server.

Fixed version:

```go
type Crawler struct {
	client *http.Client
	sem    chan struct{} // limits concurrent requests

	mu     sync.Mutex // guards seen and broken
	seen   map[string]bool
	broken []string

	wg sync.WaitGroup
}

func NewCrawler(maxConcurrent int) *Crawler {
	return &Crawler{
		client: &http.Client{Timeout: 10 * time.Second},
		sem:    make(chan struct{}, maxConcurrent),
		seen:   make(map[string]bool),
	}
}

func (c *Crawler) Run(start string, depth int) []string {
	c.wg.Add(1)
	go c.visit(start, depth)
	c.wg.Wait()
	return c.broken
}

// markSeen reports whether url is new and marks it, in one critical section.
func (c *Crawler) markSeen(url string) bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.seen[url] {
		return false
	}
	c.seen[url] = true
	return true
}

func (c *Crawler) addBroken(url string) {
	c.mu.Lock()
	c.broken = append(c.broken, url)
	c.mu.Unlock()
}

func (c *Crawler) visit(url string, depth int) {
	defer c.wg.Done()
	if depth == 0 || !c.markSeen(url) {
		return
	}

	c.sem <- struct{}{} // acquire a slot
	links, err := c.fetchLinks(url)
	<-c.sem // release it before spawning children

	if err != nil {
		c.addBroken(url)
		return
	}
	for _, l := range links {
		c.wg.Add(1)
		go c.visit(l, depth-1)
	}
}

func (c *Crawler) fetchLinks(url string) ([]string, error) {
	resp, err := c.client.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 400 {
		return nil, fmt.Errorf("%s: %s", url, resp.Status)
	}
	return extractLinks(resp), nil
}
```

Use it with `NewCrawler(8)`, which allows 8 requests in flight.

The important part is `markSeen`: the check and the write happen under **one** lock acquisition. A separate locked "is it seen?" call followed by a locked "mark it" call would remove the crash but keep the duplicate crawling.

For the future, run with the race detector. It finds this class of bug even on runs that happen not to crash:

```
go run -race .
go test -race ./...
```

It would have pointed at `crawler.go:37` and `crawler.go:41` on the first run.

Go 1.22's `ServeMux` supports methods and path parameters in patterns (`"GET /notes/{id}"`), so you no longer need a router library for this.

```go
package main

import (
	"cmp"
	"context"
	"encoding/json"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"slices"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"
)

type Note struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Body      string    `json:"body"`
	CreatedAt time.Time `json:"created_at"`
}

// NoteStore is a concurrency-safe in-memory store.
type NoteStore struct {
	mu     sync.RWMutex
	nextID int
	notes  map[int]Note
}

func NewNoteStore() *NoteStore {
	return &NoteStore{nextID: 1, notes: make(map[int]Note)}
}

func (s *NoteStore) List() []Note {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := make([]Note, 0, len(s.notes))
	for _, n := range s.notes {
		out = append(out, n)
	}
	slices.SortFunc(out, func(a, b Note) int { return cmp.Compare(a.ID, b.ID) })
	return out
}

func (s *NoteStore) Get(id int) (Note, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	n, ok := s.notes[id]
	return n, ok
}

func (s *NoteStore) Create(title, body string) Note {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := Note{ID: s.nextID, Title: title, Body: body, CreatedAt: time.Now().UTC()}
	s.notes[n.ID] = n
	s.nextID++
	return n
}

func (s *NoteStore) Delete(id int) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.notes[id]; !ok {
		return false
	}
	delete(s.notes, id)
	return true
}

type server struct {
	store *NoteStore
}

func (srv *server) routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /notes", srv.listNotes)
	mux.HandleFunc("GET /notes/{id}", srv.getNote)
	mux.HandleFunc("POST /notes", srv.createNote)
	mux.HandleFunc("DELETE /notes/{id}", srv.deleteNote)
	return mux
}

func (srv *server) listNotes(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, srv.store.List())
}

func (srv *server) getNote(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(w, r)
	if !ok {
		return
	}
	note, found := srv.store.Get(id)
	if !found {
		writeError(w, http.StatusNotFound, "note not found")
		return
	}
	writeJSON(w, http.StatusOK, note)
}

func (srv *server) createNote(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Title string `json:"title"`
		Body  string `json:"body"`
	}
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON: "+err.Error())
		return
	}
	title := strings.TrimSpace(in.Title)
	if title == "" {
		writeError(w, http.StatusUnprocessableEntity, "title is required")
		return
	}
	note := srv.store.Create(title, in.Body)
	w.Header().Set("Location", "/notes/"+strconv.Itoa(note.ID))
	writeJSON(w, http.StatusCreated, note)
}

func (srv *server) deleteNote(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(w, r)
	if !ok {
		return
	}
	if !srv.store.Delete(id) {
		writeError(w, http.StatusNotFound, "note not found")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func pathID(w http.ResponseWriter, r *http.Request) (int, bool) {
	id, err := strconv.Atoi(r.PathValue("id"))
	if err != nil || id < 1 {
		writeError(w, http.StatusBadRequest, "id must be a positive integer")
		return 0, false
	}
	return id, true
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(v); err != nil {
		log.Printf("write response: %v", err)
	}
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

func main() {
	srv := &server{store: NewNoteStore()}
	httpServer := &http.Server{
		Addr:              ":8080",
		Handler:           srv.routes(),
		ReadHeaderTimeout: 5 * time.Second,
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	go func() {
		log.Printf("listening on %s", httpServer.Addr)
		if err := httpServer.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("listen: %v", err)
		}
	}()

	<-ctx.Done()
	log.Println("shutting down, waiting up to 10s for open requests")

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := httpServer.Shutdown(shutdownCtx); err != nil {
		log.Printf("shutdown: %v", err)
	}
}
```

Try it:

```
curl -s -X POST localhost:8080/notes -d '{"title":"groceries","body":"oat milk, lemons"}'
curl -s localhost:8080/notes
curl -s localhost:8080/notes/1
curl -s -X DELETE -i localhost:8080/notes/1
```

Notes:

- **`go.mod` must say `go 1.22` or newer.** The method and wildcard patterns depend on the module's Go version. With `go 1.21` in `go.mod`, `"GET /notes/{id}"` is treated as a literal path and nothing matches.
- **The mux answers wrong methods for you:** `PUT /notes` gets `405 Method Not Allowed` with an `Allow` header, and a `GET` pattern also serves `HEAD`.
- **`Shutdown`** stops accepting new connections and waits for running requests to finish, for at most 10 seconds. `signal.NotifyContext` also catches `SIGTERM`, which is what Docker and systemd send.
- **`MaxBytesReader` + `DisallowUnknownFields`** reject huge bodies and typos like `"tilte"` instead of silently creating an untitled note.

When you add a real database later, turn `NoteStore` into an interface with the same four methods, and the handlers won't need to change.

`errgroup` with `SetLimit` covers most of it: a fixed number of goroutines, the first error cancels a shared context, and `Wait` returns that error. Progress is an atomic counter that a ticker prints once a second.

```go
package main

import (
	"context"
	"flag"
	"fmt"
	"image"
	"image/jpeg"
	"image/png"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync/atomic"
	"time"

	"golang.org/x/image/draw"
	"golang.org/x/sync/errgroup"
)

func main() {
	src := flag.String("src", "", "source directory")
	dst := flag.String("dst", "", "output directory")
	maxSide := flag.Int("max", 1600, "maximum length of the long side in pixels")
	workers := flag.Int("workers", runtime.NumCPU(), "parallel workers")
	flag.Parse()
	if *src == "" || *dst == "" {
		flag.Usage()
		os.Exit(2)
	}

	files, err := collectImages(*src)
	if err != nil {
		log.Fatalf("scan %s: %v", *src, err)
	}
	total := int64(len(files))
	log.Printf("found %d images, using %d workers", total, *workers)

	g, ctx := errgroup.WithContext(context.Background())
	g.SetLimit(*workers)

	var done atomic.Int64
	stopProgress := startProgress(&done, total)

	for _, path := range files {
		if ctx.Err() != nil {
			break // a worker failed: don't start new work
		}
		g.Go(func() error { // blocks while all workers are busy
			rel, err := filepath.Rel(*src, path)
			if err != nil {
				return err
			}
			if err := resizeFile(ctx, path, filepath.Join(*dst, rel), *maxSide); err != nil {
				return fmt.Errorf("%s: %w", path, err)
			}
			done.Add(1)
			return nil
		})
	}

	err = g.Wait()
	stopProgress()
	if err != nil {
		log.Fatalf("stopped after %d/%d files: %v", done.Load(), total, err)
	}
	log.Printf("resized %d files", total)
}

func collectImages(root string) ([]string, error) {
	var files []string
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		switch strings.ToLower(filepath.Ext(path)) {
		case ".jpg", ".jpeg", ".png":
			files = append(files, path)
		}
		return nil
	})
	return files, err
}

func resizeFile(ctx context.Context, in, out string, maxSide int) error {
	if err := ctx.Err(); err != nil {
		return err
	}

	f, err := os.Open(in)
	if err != nil {
		return err
	}
	defer f.Close()

	img, format, err := image.Decode(f)
	if err != nil {
		return fmt.Errorf("decode: %w", err)
	}

	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	if w > maxSide || h > maxSide {
		if w >= h {
			h = max(1, h*maxSide/w)
			w = maxSide
		} else {
			w = max(1, w*maxSide/h)
			h = maxSide
		}
	}
	dstImg := image.NewRGBA(image.Rect(0, 0, w, h))
	draw.CatmullRom.Scale(dstImg, dstImg.Bounds(), img, b, draw.Over, nil)

	if err := os.MkdirAll(filepath.Dir(out), 0o755); err != nil {
		return err
	}
	// Write to a temp file and rename, so a crash never leaves half-written images behind.
	tmp := out + ".tmp"
	of, err := os.Create(tmp)
	if err != nil {
		return err
	}
	if format == "png" {
		err = png.Encode(of, dstImg)
	} else {
		err = jpeg.Encode(of, dstImg, &jpeg.Options{Quality: 85})
	}
	if closeErr := of.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		os.Remove(tmp)
		return fmt.Errorf("encode: %w", err)
	}
	return os.Rename(tmp, out)
}

func startProgress(done *atomic.Int64, total int64) (stop func()) {
	ticker := time.NewTicker(time.Second)
	quit := make(chan struct{})
	finished := make(chan struct{})

	go func() {
		defer close(finished)
		defer ticker.Stop()
		for {
			select {
			case <-ticker.C:
				fmt.Fprintf(os.Stderr, "\r%d/%d", done.Load(), total)
			case <-quit:
				fmt.Fprintf(os.Stderr, "\r%d/%d\n", done.Load(), total)
				return
			}
		}
	}()

	return func() {
		close(quit)
		<-finished
	}
}
