Split the function along its three dependencies (the database, the mail server and the clock) and pass each one in. In Go you define small interfaces **where they are used**, so tests can hand in fakes, and the decision "is this invoice due soon?" becomes a pure function you can test with a table.

```go
package billing

import (
	"context"
	"database/sql"
	"fmt"
	"net/smtp"
	"time"
)

type Invoice struct {
	ID    int64
	Email string
	DueAt time.Time
}

type InvoiceSource interface {
	UnpaidInvoices(ctx context.Context) ([]Invoice, error)
}

type Mailer interface {
	Send(ctx context.Context, to, subject, body string) error
}

type Reminder struct {
	Invoices InvoiceSource
	Mail     Mailer
	Now      func() time.Time
	Window   time.Duration // e.g. 72 * time.Hour
}

// Run mails a reminder for every unpaid invoice due within Window.
func (r *Reminder) Run(ctx context.Context) (sent int, err error) {
	invoices, err := r.Invoices.UnpaidInvoices(ctx)
	if err != nil {
		return 0, fmt.Errorf("load invoices: %w", err)
	}
	now := r.Now()
	for _, inv := range invoices {
		if !dueSoon(inv.DueAt, now, r.Window) {
			continue
		}
		subject := fmt.Sprintf("Invoice %d due soon", inv.ID)
		body := fmt.Sprintf("Your invoice is due on %s.", inv.DueAt.Format("2 Jan 2006"))
		if err := r.Mail.Send(ctx, inv.Email, subject, body); err != nil {
			return sent, fmt.Errorf("invoice %d: %w", inv.ID, err)
		}
		sent++
	}
	return sent, nil
}

// dueSoon keeps the original rule: strictly inside (due-window, due).
func dueSoon(due, now time.Time, window time.Duration) bool {
	return now.After(due.Add(-window)) && now.Before(due)
}

// SQLInvoices is the production InvoiceSource.
type SQLInvoices struct{ DB *sql.DB }

func (s SQLInvoices) UnpaidInvoices(ctx context.Context) ([]Invoice, error) {
	rows, err := s.DB.QueryContext(ctx, `SELECT id, email, due_at FROM invoices WHERE paid = false`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Invoice
	for rows.Next() {
		var inv Invoice
		if err := rows.Scan(&inv.ID, &inv.Email, &inv.DueAt); err != nil {
			return nil, err
		}
		out = append(out, inv)
	}
	return out, rows.Err()
}

// SMTPMailer is the production Mailer.
type SMTPMailer struct{ Addr, From string }

func (m SMTPMailer) Send(_ context.Context, to, subject, body string) error {
	msg := "Subject: " + subject + "\r\n\r\n" + body
	return smtp.SendMail(m.Addr, nil, m.From, []string{to}, []byte(msg))
}
```

