```go
package billing

import (
	"context"
	"testing"
	"time"
)

func TestDueSoon(t *testing.T) {
	due := time.Date(2024, 3, 10, 12, 0, 0, 0, time.UTC)
	tests := []struct {
		name string
		now  time.Time
		want bool
	}{
		{"four days before", due.Add(-96 * time.Hour), false},
		{"exactly 72h before", due.Add(-72 * time.Hour), false},
		{"two days before", due.Add(-48 * time.Hour), true},
		{"one minute before", due.Add(-time.Minute), true},
		{"at due time", due, false},
		{"overdue", due.Add(time.Hour), false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := dueSoon(due, tt.now, 72*time.Hour); got != tt.want {
				t.Errorf("dueSoon(now=%v) = %v, want %v", tt.now, got, tt.want)
			}
		})
	}
}

type fakeInvoices []Invoice

func (f fakeInvoices) UnpaidInvoices(context.Context) ([]Invoice, error) { return f, nil }

type recordingMailer struct{ to []string }

func (m *recordingMailer) Send(_ context.Context, to, _, _ string) error {
	m.to = append(m.to, to)
	return nil
}

func TestReminderSendsOnlyDueSoon(t *testing.T) {
	now := time.Date(2024, 3, 8, 9, 0, 0, 0, time.UTC)
	mail := &recordingMailer{}
	r := &Reminder{
		Invoices: fakeInvoices{
			{ID: 1, Email: "a@example.test", DueAt: now.Add(24 * time.Hour)},
			{ID: 2, Email: "b@example.test", DueAt: now.Add(10 * 24 * time.Hour)},
			{ID: 3, Email: "c@example.test", DueAt: now.Add(-time.Hour)},
		},
		Mail:   mail,
		Now:    func() time.Time { return now },
		Window: 72 * time.Hour,
	}

	sent, err := r.Run(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if sent != 1 || len(mail.to) != 1 || mail.to[0] != "a@example.test" {
		t.Fatalf("sent=%d to=%v, want exactly one mail to a@example.test", sent, mail.to)
	}
}
```

Why it's split this way:

- **The interfaces are tiny and live in `billing`**, the package that consumes them. `SQLInvoices` and `SMTPMailer` don't need to know they implement anything.
- **The clock is a `func() time.Time`, not an interface.** It's the lightest thing that works. `time.Now` itself fits the type.
- **The edge cases now have names.** The old code computed `time.Now()` twice, so in theory the two comparisons could see different times. Now `now` is read once per run.
- **The SQL query itself still deserves one integration test** against a real Postgres (testcontainers, or a `docker compose` service in CI). Keep that test separate and tag it (`//go:build integration`), so `go test ./...` stays fast.

