    public required string Instructions { get; set; }

    public List<Ingredient> Ingredients { get; set; } = [];

    public int Servings { get; set; } = 1;
}

public class Ingredient
{
    public int Id { get; set; }

    public required string Name { get; set; }

    public decimal Quantity { get; set; }

    public string? Unit { get; set; }           // "2 eggs" has no unit

    public int RecipeId { get; set; }
    public Recipe Recipe { get; set; } = null!; // set by EF when loaded
}
```

The rule for each kind:

| Property | Fix | Why |
|---|---|---|
| Strings that must have a value (`Title`) | `required` | Your own code *must* set it in `new Recipe { ... }`, or it won't compile. EF Core materializes entities with reflection and isn't affected. |
| Collection navigations (`Ingredients`) | `= []` | An empty list is a valid value. It also stops `recipe.Ingredients.Add(...)` from throwing on a new recipe. |
| Reference navigations (`Ingredient.Recipe`) | `= null!` | This is the one place where `null!` is the recommended pattern. EF sets it when you load or `Include` it, and the FK is required. |
| Really optional values (`Unit`) | `string?` | Say what's true. |

**Watch out with "just make it `string?`".** Since nullable reference types are on, EF Core uses them to decide the column's nullability. Changing `string Title` to `string? Title` makes the next migration turn `Title` into a nullable column. After `dotnet ef migrations add`, look at the generated migration for any `nullable: true` you didn't intend.

For DTOs and view models (not entities), `required` or a record with a primary constructor is usually the cleanest choice, so `null!` stays limited to EF navigations.

Keep `Program.cs` to service registration plus one `app.MapTicketEndpoints()` call. Put each feature's endpoints in an extension method on a route group, and use `TypedResults` so the possible responses are part of each handler's signature (and show up in OpenAPI).

**Program.cs**

```csharp
using System.Text.Json.Serialization;
using Helpdesk;
using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<HelpdeskDb>(options =>
    options.UseSqlite(builder.Configuration.GetConnectionString("Helpdesk") ?? "Data Source=helpdesk.db"));
builder.Services.AddProblemDetails();
builder.Services.ConfigureHttpJsonOptions(options =>
    options.SerializerOptions.Converters.Add(new JsonStringEnumConverter()));

var app = builder.Build();

app.UseExceptionHandler();
app.UseStatusCodePages();

app.MapTicketEndpoints();

app.Run();
```

**Tickets/Model.cs**

```csharp
using Microsoft.EntityFrameworkCore;

namespace Helpdesk;

public enum TicketStatus { Open, InProgress, Resolved, Closed }
public enum Priority { Low, Normal, High, Critical }

public class Ticket
{
    public int Id { get; set; }
    public required string Title { get; set; }
    public string? Description { get; set; }
    public Priority Priority { get; set; } = Priority.Normal;
    public TicketStatus Status { get; set; } = TicketStatus.Open;
    public DateTime CreatedUtc { get; set; } = DateTime.UtcNow;
}

public class HelpdeskDb(DbContextOptions<HelpdeskDb> options) : DbContext(options)
{
    public DbSet<Ticket> Tickets => Set<Ticket>();
}

public record NewTicket(string Title, string? Description, Priority? Priority);
public record TicketPatch(string? Title, string? Description, Priority? Priority, TicketStatus? Status);

public record TicketDto(int Id, string Title, string? Description, Priority Priority, TicketStatus Status, DateTime CreatedUtc)
{
    public static TicketDto From(Ticket t) => new(t.Id, t.Title, t.Description, t.Priority, t.Status, t.CreatedUtc);
}
```

**Tickets/TicketEndpoints.cs**

```csharp
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.EntityFrameworkCore;

namespace Helpdesk;

public static class TicketEndpoints
{
    public static RouteGroupBuilder MapTicketEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/tickets").WithTags("Tickets");

        group.MapGet("/", GetAll);
        group.MapGet("/{id:int}", GetById);
        group.MapPost("/", Create);
        group.MapPatch("/{id:int}", Update);
        group.MapDelete("/{id:int}", Delete);

        return group;
    }

    static async Task<Ok<List<TicketDto>>> GetAll(HelpdeskDb db, TicketStatus? status, Priority? minPriority)
    {
        IQueryable<Ticket> query = db.Tickets.AsNoTracking();
        if (status is not null)
            query = query.Where(t => t.Status == status);
        if (minPriority is not null)
            query = query.Where(t => t.Priority >= minPriority);

        var tickets = await query
            .OrderByDescending(t => t.Priority)
            .ThenBy(t => t.CreatedUtc)
            .Select(t => TicketDto.From(t))
            .ToListAsync();
        return TypedResults.Ok(tickets);
    }

    static async Task<Results<Ok<TicketDto>, NotFound>> GetById(int id, HelpdeskDb db) =>
        await db.Tickets.FindAsync(id) is { } ticket
            ? TypedResults.Ok(TicketDto.From(ticket))
            : TypedResults.NotFound();

    static async Task<Results<Created<TicketDto>, ValidationProblem>> Create(NewTicket input, HelpdeskDb db)
    {
        if (string.IsNullOrWhiteSpace(input.Title) || input.Title.Length > 200)
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["title"] = ["Title is required and must be at most 200 characters."],
            });
        }

        var ticket = new Ticket
        {
            Title = input.Title.Trim(),
            Description = input.Description,
            Priority = input.Priority ?? Priority.Normal,
        };
        db.Tickets.Add(ticket);
        await db.SaveChangesAsync();

        return TypedResults.Created($"/api/tickets/{ticket.Id}", TicketDto.From(ticket));
    }

    static async Task<Results<Ok<TicketDto>, NotFound>> Update(int id, TicketPatch patch, HelpdeskDb db)
    {
        var ticket = await db.Tickets.FindAsync(id);
        if (ticket is null)
            return TypedResults.NotFound();

        if (!string.IsNullOrWhiteSpace(patch.Title)) ticket.Title = patch.Title.Trim();
        if (patch.Description is not null) ticket.Description = patch.Description;
        if (patch.Priority is { } priority) ticket.Priority = priority;
        if (patch.Status is { } status) ticket.Status = status;

        await db.SaveChangesAsync();
        return TypedResults.Ok(TicketDto.From(ticket));
    }

    static async Task<Results<NoContent, NotFound>> Delete(int id, HelpdeskDb db) =>
        await db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync() == 1
            ? TypedResults.NoContent()
            : TypedResults.NotFound();
}
```

Create the database:

```
dotnet add package Microsoft.EntityFrameworkCore.Sqlite
dotnet add package Microsoft.EntityFrameworkCore.Design
dotnet ef migrations add InitialCreate
dotnet ef database update
```

Example calls:

```
GET  /api/tickets?status=Open&minPriority=High
POST /api/tickets          {"title": "Printer on 3rd floor offline", "priority": "High"}
PATCH /api/tickets/7       {"status": "Resolved"}
```

Why this layout:

- **Each handler is a `static` method, not a lambda.** It's testable on its own (call `Create(new NewTicket(...), db)` with an in-memory SQLite connection), and a stack trace shows a real method name.
- **`Results<Ok<T>, NotFound>`** documents every possible response in the signature, and the compiler checks that you only return those.
- **DTOs instead of entities in and out.** Clients can't set `Id` or `CreatedUtc`, and you can change the table without breaking the API.
- **`JsonStringEnumConverter`** makes the JSON say `"High"` instead of `2`. Your team will read these payloads in logs.
- **`ExecuteDeleteAsync`** deletes in one SQL statement, without loading the entity first.

When a second feature arrives (assets, users), give it its own `XyzEndpoints.cs` with the same pattern, and `Program.cs` grows by one line per feature.

unity 2022 3D. my player can jump infinitely while in the air, and the movement jitters especially when the camera follows. here's my script

```csharp
using UnityEngine;

public class PlayerMovement : MonoBehaviour
{
    public float speed = 6f;
    public float jumpForce = 5f;
    Rigidbody rb;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
    }

    void Update()
    {
        float h = Input.GetAxis("Horizontal");
        float v = Input.GetAxis("Vertical");
        transform.Translate(new Vector3(h, 0, v) * speed * Time.deltaTime);

        if (Input.GetKeyDown(KeyCode.Space))
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
    }
}
```

Two separate problems:

1. **Infinite jumps:** nothing checks whether the player is on the ground.
2. **Jitter:** you move the object with `transform.Translate` in `Update` while a `Rigidbody` is also simulating it in `FixedUpdate`. The two fight each other every frame. When you have a Rigidbody, move it **through** the Rigidbody, and do it in `FixedUpdate`.

The rule: read input in `Update` (so no key press is missed), apply physics in `FixedUpdate`.

```csharp
using UnityEngine;

[RequireComponent(typeof(Rigidbody))]
public class PlayerMovement : MonoBehaviour
{
    [SerializeField] float speed = 6f;
    [SerializeField] float jumpHeight = 1.2f;       // in metres, easier to tune than a force
    [SerializeField] Transform groundCheck;         // empty child object at the feet
    [SerializeField] float groundRadius = 0.25f;
    [SerializeField] LayerMask groundMask;

    Rigidbody rb;
    Vector3 moveInput;
    bool jumpQueued;
    bool isGrounded;

    void Awake()
    {
        rb = GetComponent<Rigidbody>();
        rb.interpolation = RigidbodyInterpolation.Interpolate; // smooth between physics steps
        rb.freezeRotation = true;                              // don't tip over
    }

    void Update()
    {
        moveInput = new Vector3(Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical"));
        moveInput = Vector3.ClampMagnitude(moveInput, 1f); // diagonals aren't faster

        if (Input.GetButtonDown("Jump"))
            jumpQueued = true;
    }

    void FixedUpdate()
    {
        isGrounded = Physics.CheckSphere(groundCheck.position, groundRadius, groundMask,
                                         QueryTriggerInteraction.Ignore);

        Vector3 move = transform.TransformDirection(moveInput) * speed;
        Vector3 velocity = rb.velocity;
        velocity.x = move.x;
        velocity.z = move.z;

        if (jumpQueued && isGrounded)
        {
            // v = sqrt(2gh): reaches jumpHeight regardless of the Rigidbody's mass
            velocity.y = Mathf.Sqrt(2f * -Physics.gravity.y * jumpHeight);
        }
        jumpQueued = false;

        rb.velocity = velocity;
    }

    void OnDrawGizmosSelected()
    {
        if (groundCheck == null) return;
        Gizmos.color = isGrounded ? Color.green : Color.red;
        Gizmos.DrawWireSphere(groundCheck.position, groundRadius);
    }
}
```

Setup in the editor:

1. Create an empty child of the player called `GroundCheck`, and put it at the bottom of the collider (for a default capsule, y = -1).
2. Put your floor and platforms on a layer called `Ground`, and select **only** that layer in `Ground Mask`. If the player's own layer is included, the sphere always touches the player's own collider, and you're back to infinite jumps.
3. Select the player in the Scene view. The gizmo sphere turns green when standing and red in the air, which makes tuning the radius easy.
4. If the camera follows the player, move the camera in `LateUpdate`, so it follows the interpolated position.

Why the jump sets `velocity.y` instead of `AddForce`: an impulse adds to whatever vertical speed the player already has. Jumping while still moving up from a slope would launch them higher. Setting the velocity gives the same jump every time.

If you upgrade to Unity 6 later: `rb.velocity` is renamed to `rb.linearVelocity` there. The old name still works but gives an obsolete warning.

Xcode 16, I switched my bird watching app to Swift 6 language mode and now this view model has 4 errors like:

```
SightingsModel.swift:24:22 Main actor-isolated property 'errorMessage' can not be mutated from a Sendable closure
```

```swift
import Foundation
import Observation

struct Sighting: Identifiable, Decodable {
    let id: UUID
    let species: String
    let seenAt: Date
    let location: String
}

@MainActor
@Observable
final class SightingsModel {
    var sightings: [Sighting] = []
    var isLoading = false
    var errorMessage: String?

    func load() {
        isLoading = true
        let url = URL(string: "https://api.birdlog.example/v1/sightings")!
        URLSession.shared.dataTask(with: url) { data, _, error in
            if let error {
                self.errorMessage = error.localizedDescription
                self.isLoading = false
                return
            }
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .iso8601
            if let data, let decoded = try? decoder.decode([Sighting].self, from: data) {
                self.sightings = decoded
            }
            self.isLoading = false
        }.resume()
    }
}
```

The compiler is right. `dataTask`'s completion handler runs on a background queue that URLSession picks, but `SightingsModel` is `@MainActor`, so its properties may only be touched on the main actor. In Swift 5 mode this was a silent data race, sometimes visible as UI updates that "randomly" didn't appear. Swift 6 makes it a compile error.

The clean fix is to stop using the completion-handler API. With `async`/`await`, the method stays on the main actor the whole time, and only the network wait is suspended:

```swift
import Foundation
import Observation

struct Sighting: Identifiable, Decodable {
    let id: UUID
    let species: String
    let seenAt: Date
    let location: String
}

@MainActor
@Observable
final class SightingsModel {
    private(set) var sightings: [Sighting] = []
    private(set) var isLoading = false
    private(set) var errorMessage: String?

    private let url = URL(string: "https://api.birdlog.example/v1/sightings")!

    func load() async {
        isLoading = true
        errorMessage = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: url)
            guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode) else {
                throw URLError(.badServerResponse)
            }
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .iso8601
            sightings = try decoder.decode([Sighting].self, from: data)
        } catch let error as URLError where error.code == .cancelled {
            // the view went away or the refresh was replaced: keep the current list
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    func dismissError() {
        errorMessage = nil
    }
}
```

In the view, `.task` starts the load when the view appears and cancels it when it disappears. `.refreshable` gives you pull-to-refresh for free:

```swift
import SwiftUI

struct SightingsView: View {
    @State private var model = SightingsModel()

    var body: some View {
        NavigationStack {
            List(model.sightings) { sighting in
                VStack(alignment: .leading) {
                    Text(sighting.species).font(.headline)
                    Text("\(sighting.location) · \(sighting.seenAt.formatted(date: .abbreviated, time: .shortened))")
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
            .overlay {
                if model.isLoading && model.sightings.isEmpty {
                    ProgressView()
                }
            }
            .navigationTitle("Sightings")
            .task { await model.load() }
            .refreshable { await model.load() }
            .alert(
                "Could not load sightings",
                isPresented: Binding(
                    get: { model.errorMessage != nil },
                    set: { if !$0 { model.dismissError() } }
                )
            ) {
                Button("OK", role: .cancel) {}
            } message: {
                Text(model.errorMessage ?? "")
            }
        }
    }
}
```

What changed besides the concurrency fix:

- **`try?` is gone.** The old code silently ignored decoding errors, so a renamed API field just showed an empty list. Now the user sees the error, and so do you during development.
- **The HTTP status is checked.** A 500 response with an HTML error page used to go into the JSON decoder.
- **Cancellation isn't shown as an error.** URLSession reports a cancelled task as `URLError(.cancelled)`, not as `CancellationError`, which is why the `catch` matches that code.
- **The setters are `private(set)`.** Views can read the state, but only the model changes it.

If you ever do need a callback-based API from a `@MainActor` type, hop back explicitly with `Task { @MainActor in ... }` inside the callback. For URLSession, though, the async API is the better tool.

inherited the php site of our small sports club. a friend said the login is "sql injectable" and also passwords are stored badly. can you fix it? server has PHP 8.2 and MySQL. this is login.php:

```php
<?php
session_start();
$conn = mysqli_connect("localhost", "club", "club123", "clubdb");

if ($_SERVER['REQUEST_METHOD'] == 'POST') {
    $user = $_POST['username'];
    $pass = md5($_POST['password']);
    $sql = "SELECT * FROM members WHERE username = '$user' AND password = '$pass'";
    $result = mysqli_query($conn, $sql);
    if (mysqli_num_rows($result) == 1) {
        $row = mysqli_fetch_assoc($result);
        $_SESSION['member_id'] = $row['id'];
        $_SESSION['is_admin'] = $row['is_admin'];
        header("Location: dashboard.php");
    } else {
        $error = "Wrong username or password";
    }
}
?>
<form method="post">
  <?php if (isset($error)) echo "<p>$error</p>"; ?>
  <input name="username" value="<?php echo $_POST['username']; ?>">
  <input type="password" name="password">
  <button>Login</button>
</form>
```

Your friend is right, and it's worse than that. This page has five problems:

1. **SQL injection.** Typing `admin' -- ` as the username logs you in as admin without a password.
2. **MD5 passwords.** They're unsalted and fast to crack. Most of them can be looked up in public tables within seconds.
3. **XSS in the form.** The username is echoed back without escaping.
4. **No `exit` after the redirect.** The rest of the page still runs and is sent to the browser.
5. **Session fixation.** The session ID isn't renewed after login.

Here's a fixed version. It also **upgrades the old MD5 hashes** the first time each member logs in, so nobody has to reset their password.

**config/db.php** (keep this outside the web root if your host allows it):

```php
<?php
declare(strict_types=1);

$pdo = new PDO(
    'mysql:host=localhost;dbname=clubdb;charset=utf8mb4',
    getenv('CLUB_DB_USER') ?: 'club',
    getenv('CLUB_DB_PASS') ?: '',
    [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES => false,
    ]
);
```

**login.php**

```php
<?php
declare(strict_types=1);

session_start();
require __DIR__ . '/../config/db.php';

$error = null;
$username = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = trim((string)($_POST['username'] ?? ''));
    $password = (string)($_POST['password'] ?? '');

    $stmt = $pdo->prepare('SELECT id, password, is_admin FROM members WHERE username = :username');
    $stmt->execute(['username' => $username]);
    $member = $stmt->fetch();

    if ($member && check_password($pdo, (int)$member['id'], $password, $member['password'])) {
        session_regenerate_id(true);
        $_SESSION['member_id'] = (int)$member['id'];
        $_SESSION['is_admin'] = (bool)$member['is_admin'];
        header('Location: dashboard.php');
        exit;
    }
    $error = 'Wrong username or password';
}

/**
 * Checks the password. Old accounts still have unsalted MD5 hashes; those are
 * replaced with password_hash() on the first successful login.
 */
function check_password(PDO $pdo, int $id, string $password, string $stored): bool
{
    if (password_get_info($stored)['algo'] !== null) {
        $ok = password_verify($password, $stored);
        if ($ok && password_needs_rehash($stored, PASSWORD_DEFAULT)) {
            update_hash($pdo, $id, $password);
        }
        return $ok;
    }

    // legacy MD5 hash
    if (hash_equals($stored, md5($password))) {
        update_hash($pdo, $id, $password);
        return true;
    }
    return false;
}

function update_hash(PDO $pdo, int $id, string $password): void
{
    $stmt = $pdo->prepare('UPDATE members SET password = :hash WHERE id = :id');
    $stmt->execute(['hash' => password_hash($password, PASSWORD_DEFAULT), 'id' => $id]);
}
?>
<form method="post">
  <?php if ($error !== null): ?>
    <p class="error"><?= htmlspecialchars($error, ENT_QUOTES) ?></p>
  <?php endif; ?>
  <input name="username" value="<?= htmlspecialchars($username, ENT_QUOTES) ?>" autocomplete="username" required>
  <input type="password" name="password" autocomplete="current-password" required>
  <button>Login</button>
</form>
```

Before you deploy it:

1. **Widen the password column.** MD5 hashes are 32 characters, bcrypt hashes are 60, and future algorithms can be longer:
   ```sql
   ALTER TABLE members MODIFY password VARCHAR(255) NOT NULL;
   ```
2. **Move the database password out of the code.** Set `CLUB_DB_USER` and `CLUB_DB_PASS` in your hosting panel or in the Apache/PHP-FPM config. Since `club123` has been sitting in the PHP files (and probably in a backup or two), change it on the MySQL side too.
3. **Search for other queries built the same way:** `grep -rn "mysqli_query" .` Every query that puts `$_GET` or `$_POST` into SQL needs the same `prepare`/`execute` treatment, including the member list and the event sign-up pages, if you have them.
4. **After a few months,** members who never logged in still have MD5 hashes. Force a password reset for those accounts, or wrap the old hashes once (`password_hash(md5_hash)`) and check them accordingly.

Worth adding next, but not urgent: a CSRF token on the form, and a simple limit on failed logins per IP address.
